import java.io.*;import java.util.*;public class Main{public static void main(String[] args) throws Exception{BufferedReader br=new BufferedReader(new InputStreamReader(System.in));StringBuilder out=new StringBuilder();int T=Integer.parseInt(br.readLine().trim());while(T-- >0){int N=Integer.parseInt(br.readLine().trim());int[] best=new int[9];for(int i=0;i<N;i++){StringTokenizer st=new StringTokenizer(br.readLine());int p=Integer.parseInt(st.nextToken());int s=Integer.parseInt(st.nextToken());if(p>=1 && p<=8){if(s>best[p])best[p]=s;}}int total=0;for(int i=1;i<=8;i++)total+=best[i];out.append(total).append('\n');}System.out.print(out.toString());}}